import type { ProfileRecords } from '../../storage/profiles/ProfileRecords';

interface ScheduleOptions {
  records: ProfileRecords;
  isActive: () => boolean;
  onReady: (id: string) => void;
}
const MAX_TIMER_MS = 2_147_483_647;

export class ProfileImportSchedule {
  private readonly timers = new Map<string, ReturnType<typeof setTimeout>>();
  constructor(private readonly options: ScheduleOptions) {}

  isReady(id: string): boolean {
    const timer = this.timers.get(id);
    if (timer) clearTimeout(timer);
    this.timers.delete(id);
    if (!this.options.isActive() || !this.options.records.profile().isEnabled)
      return false;
    const job = this.options.records.jobs().find((item) => item.id === id);
    if (!job || job.state !== 'pending') return false;
    if (!job.retryAt) return true;
    const wait = Math.max(1, Date.parse(job.retryAt) - Date.now());
    const next = setTimeout(
      () => {
        this.timers.delete(id);
        if (this.isReady(id)) this.options.onReady(id);
      },
      Math.min(MAX_TIMER_MS, wait),
    );
    next.unref();
    this.timers.set(id, next);
    return false;
  }

  stop(): void {
    for (const timer of this.timers.values()) clearTimeout(timer);
    this.timers.clear();
  }
}
